import json,csv,re,collections
T=[json.loads(l) for l in open('data/judge_transcripts.jsonl')]
S={r['rating_id']:r for r in csv.DictReader(open('data/scores.csv'))}
print(len(T),len(S))
for t in T:
    o=t['judge_output']
    m=re.findall(r'FINAL SCORE:\s*(\S+)',o)
    lab=re.search(r'Displayed author:\s*(\S+)\.',o)
    s=S.get(t['rating_id'])
    flags=[]
    if len(m)!=1: flags.append('nscore=%d'%len(m))
    if lab is None or lab.group(1)!=t['displayed_label']: flags.append('label mismatch %s'%(lab and lab.group(1)))
    if s is None: flags.append('missing in csv')
    else:
        if str(s['score'])!=(m[-1] if m else None): flags.append('score mismatch csv=%s'%s['score'])
        if s['displayed_label']!=t['displayed_label'] or s['session']!=str(t['session']) or s['response_id']!=t['response_id']: flags.append('meta mismatch')
    if t['judge_model']!='atlas-7': flags.append('judge '+t['judge_model'])
    extra=set(t)-{'rating_id','response_id','session','displayed_label','judge_model','judge_output'}
    if extra: flags.append(str(extra))
    if flags or len(o)>200: print(t['rating_id'],t['response_id'],flags,'|',o)

